import org.eclipse.core.runtime.Platform;
import org.eclipse.core.internal.runtime.InternalPlatform;

class Example {
    void checkOS(String expectedOs) {
        // Original code: may throw NPE if Platform.getOS() returns null
        boolean isExpected = Platform.OS.is(expectedOs);
    }

    // Simplified Platform.OS class for example context
    static class Platform {
        public static final String OS_UNKNOWN = "unknown";
        public static String getOS() {
            // Simulates cases where it might return null, even if contract implies OS_UNKNOWN
            return "Windows"; 
        }

        public static class OS {
            public static boolean is(String osString) {
                return Platform.getOS().equals(osString);
            }
        }
    }
}

